import app from 'flarum/admin/app';
export class AdminApiError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}
function url(path) {
  return app.forum.attribute('apiUrl') + path;
}
function detail(error) {
  return error?.response?.errors?.[0]?.detail || error?.message || app.translator.trans('cengizkemec-social.admin.errors.generic');
}
export async function adminRequest(method, path, body) {
  const options = {
    method,
    url: url(path),
    errorHandler: () => {}
  };
  if (body !== undefined) options.body = body;
  try {
    return await app.request(options);
  } catch (error) {
    throw new AdminApiError(detail(error), Number(error?.status || 0));
  }
}
export const adminGet = (path, params = {}) => {
  const query = Object.keys(params).filter(key => params[key] !== undefined && params[key] !== null && params[key] !== '').map(key => encodeURIComponent(key) + '=' + encodeURIComponent(String(params[key]))).join('&');
  return adminRequest('GET', path + (query ? '?' + query : ''));
};
export const adminPost = (path, body = {}) => adminRequest('POST', path, body);
export const adminPatch = (path, body = {}) => adminRequest('PATCH', path, body);
export const adminDelete = path => adminRequest('DELETE', path);